CREATE TABLE IF NOT EXISTS Alerts(Id INTEGER PRIMARY KEY AUTOINCREMENT,Name TEXT UNIQUE,Enabled INTEGER DEFAULT 1,ReportPath TEXT,FilterJson TEXT,ContainsFilter TEXT,Severity TEXT,LastRun TEXT,LastMatches INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS AlertHistory(Id INTEGER PRIMARY KEY AUTOINCREMENT,AlertId INTEGER NOT NULL,TriggeredOn TEXT NOT NULL,Severity TEXT,MatchCount INTEGER,Details TEXT,Acknowledged INTEGER DEFAULT 0,AcknowledgedBy TEXT,AcknowledgedOn TEXT,FOREIGN KEY(AlertId) REFERENCES Alerts(Id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS NotificationQueue(Id INTEGER PRIMARY KEY AUTOINCREMENT,AlertId INTEGER,NotificationType TEXT,Recipient TEXT,Subject TEXT,Payload TEXT,Status TEXT DEFAULT 'Queued',Attempts INTEGER DEFAULT 0,CreatedOn TEXT,SentOn TEXT,LastError TEXT,FOREIGN KEY(AlertId) REFERENCES Alerts(Id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS IX_NotificationQueue_Status ON NotificationQueue(Status,CreatedOn);
